/* Loads the static RSS snapshot generated by GitHub Actions. */
window.RSS = (function () {
  "use strict";

  var CACHE_KEY = "techpulse:v2:snapshot";

  function readCache() {
    try {
      var raw = localStorage.getItem(CACHE_KEY);
      if (!raw) return null;
      var cached = JSON.parse(raw);
      return cached && Array.isArray(cached.items) ? cached : null;
    } catch (e) {
      return null;
    }
  }

  function writeCache(snapshot) {
    try {
      localStorage.setItem(CACHE_KEY, JSON.stringify(snapshot));
    } catch (e) {
      /* storage full or disabled — not fatal */
    }
  }

  function getFeed() {
    var snapshotUrl = "./feed.json?refresh=" + Date.now();
    return fetch(snapshotUrl, { cache: "no-store" })
      .then(function (res) {
        if (!res.ok) throw new Error("Feed snapshot HTTP " + res.status);
        return res.json();
      })
      .then(function (snapshot) {
        if (!snapshot || !Array.isArray(snapshot.items)) {
          throw new Error("Feed snapshot has an invalid format");
        }
        snapshot.stale = false;
        writeCache(snapshot);
        return snapshot;
      })
      .catch(function (error) {
        var cached = readCache();
        if (cached) {
          cached.stale = true;
          return cached;
        }
        throw error;
      });
  }

  return {
    getFeed: getFeed,
  };
})();
